import json, sys, urllib.parse
sys.stdout.reconfigure(encoding='utf-8')

def norm_url(url):
    try:
        p = urllib.parse.urlparse(url.lower())
        q = urllib.parse.parse_qs(p.query)
        for k in ['utm_source','utm_medium','utm_campaign','utm_content','utm_term','ref','fbclid','gclid']:
            q.pop(k, None)
        new_q = urllib.parse.urlencode({k: v[0] for k, v in q.items()})
        path = p.path.rstrip('/')
        return p.netloc + path + (('?' + new_q) if new_q else '')
    except:
        return url

